const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-118.423217, 34.770153]);
  const region = point.buffer(300); // 300-meter radius
  const date = '2020-04-14';

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  const landsat = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  const collectionSize = landsat.size().getInfo();
  console.log(`Landsat images on ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the image and apply scaling factors
  const image = landsat.first();
  const scaled = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'])
    .multiply(0.0000275).add(-0.2);

  // Apply cloud mask using QA band
  const qa = image.select('QA_PIXEL');
  const cloudMask = qa.bitwiseAnd(1 << 3)  // Cloud shadow
    .or(qa.bitwiseAnd(1 << 4))  // Snow
    .or(qa.bitwiseAnd(1 << 5))  // Cloud
    .eq(0);
  const masked = scaled.updateMask(cloudMask);

  // Calculate NDWI (Green - NIR) / (Green + NIR)
  const ndwi = masked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

  // Get NIR band for additional analysis
  const nir = masked.select('SR_B5').rename('NIR');

  // Combine for analysis
  const analysisImg = ee.Image.cat([ndwi, nir]);

  // 3. Check valid pixels
  const pixelCount = analysisImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCount.NDWI || 0;
  console.log(`Valid pixels after masking: ${validPixels}`);

  if (validPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate statistics
  const stats = analysisImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const meanNDWI = stats.NDWI;
  const meanNIR = stats.NIR;

  console.log(`Mean NDWI: ${meanNDWI?.toFixed(3)}`);
  console.log(`Mean NIR reflectance: ${meanNIR?.toFixed(3)}`);

  // 5. Validation & Classification
  if (meanNDWI === null || meanNDWI === undefined || 
      meanNIR === null || meanNIR === undefined ||
      isNaN(meanNDWI) || isNaN(meanNIR)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Classification logic
  // Water: High NDWI (>0.1), low NIR reflectance (<0.15)
  // Solar farm: Low/negative NDWI, high NIR reflectance (>0.2)
  const isWater = meanNDWI > 0.1 && meanNIR < 0.15;
  const isSolarFarm = meanNDWI < 0 && meanNIR > 0.2;

  if (isSolarFarm) {
    console.log("Classification: Solar farm");
    console.log("<answer>A</answer>");
  } else if (isWater) {
    console.log("Classification: Water pond");
    console.log("<answer>B</answer>");
  } else {
    console.log("Classification: Neither clear water nor solar farm");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
